xml.Script:
        K := 0.6;

        f := 1/sqrt(3);

        // Rotate p around normalized v
        procedure RotatePoint(Xp, Yp, Zp, Xv, Yv, Zv, Angle);
        begin
            ca := Cos(Angle);
            sa := Sin(Angle);
            c2 := 1 - ca;

            px[i] := Xp * (Xv * c2 * Xv + ca) +
                     Yp * (Yv * c2 * Xv - sa * Zv) +
                     Zp * (Zv * c2 * Xv + sa * Yv);

            py[i] := Xp * (Xv * c2 * Yv + sa * Zv) +
                     Yp * (Yv * c2 * Yv + ca) +
                     Zp * (Zv * c2 * Yv - sa * Xv);

            pz[i] := Xp * (Xv * c2 * Zv - sa * Yv) +
                     Yp * (Yv * c2 * Zv + sa * Xv) +
                     Zp * (Zv * c2 * Zv + ca);
            Inc(i);
        end;

        i := 0;
        RotatePoint ( 1, 1, 0, -f, f,-f, -1*pi/6);
        RotatePoint ( 1, 1, 0, -f, f,-f, -3*pi/6);
        RotatePoint ( 1, 1, 0, -f, f,-f, -5*pi/6);
        RotatePoint ( 0, 1, 1, -f,-f, f, -1*pi/6);
        RotatePoint ( 0, 1, 1, -f,-f, f, -3*pi/6);
        RotatePoint ( 0, 1, 1, -f,-f, f, -5*pi/6);
        RotatePoint (-1,-1, 0,  f,-f,-f, -1*pi/6);
        RotatePoint (-1,-1, 0,  f,-f,-f, -3*pi/6);
        RotatePoint (-1,-1, 0,  f,-f,-f, -5*pi/6);
        RotatePoint ( 0,-1, 1,  f, f, f, -1*pi/6);
        RotatePoint ( 0,-1, 1,  f, f, f, -3*pi/6);
        RotatePoint ( 0,-1, 1,  f, f, f, -5*pi/6);

        D := K * 0.71029864124335 * (px[8] + py[8]) / sqrt(2); // C20*(px[8]+py[8])/sqrt(2)
